-- Uses block (SPEC D-052): vendor price, then the item's exits through the recipe graph, valued per unit of this item
-- at the house you stand at. Data: ns.USES from Data/Uses.lua (generated by `wowf-analysis export-addon`, gitignored).
--   Vendor        1s 50c/u · x20 30s
--   Best use      Cooking → Longjaw Mud Snapper → AH +1c/u        (what you can do now)
--   Upside        Leatherworking → X → AH +4s/u (pattern)         (grey: behind a pattern or more skill)
--     Cooking 50 · Longjaw Mud Snapper     vendor +0c · AH +1c
--     Disenchant                           +2s 10c
-- Gains are per unit of this item over its best raw exit (max of vendor and AH net here). Pure except Ranks().
local _, ns = ...
local L = ns.L

local type, tonumber, ipairs, floor, format, concat, pcall = type, tonumber, ipairs, math.floor, string.format, table.concat, pcall

local Exits = {}
ns.Exits = Exits

Exits.MIN_GAIN, Exits.MIN_PCT = 100, 0.10 -- a craft "wins" only by at least 1s or 10 % per unit
-- Forever's per-expansion child skill lines -> the base profession (SkillLine.ParentSkillLineID, wowf DB2).
Exits.CHILD = { [2937] = 171, [2938] = 164, [2939] = 185, [2940] = 333, [2941] = 202, [2942] = 129, [2945] = 165,
  [2946] = 186, [2948] = 197 }
local TAG = { v = "vendor", a = "AH", d = "DE", c = "craft" }

local GREY, GREEN, RED, YELLOW, WHITE = "ffa0a0a0", "ff40e060", "ffff5050", "ffffd200", "ffffffff"
local function C(color, text) return "|c" .. color .. text .. "|r" end

local function Split(s, sep)
  local out, i = {}, 1
  while true do
    local j = s:find(sep, i, true)
    if not j then out[#out + 1] = s:sub(i) return out end
    out[#out + 1] = s:sub(i, j - 1)
    i = j + 1
  end
end

local cache, cacheOf = {}, nil
-- { sell, keep = {[house]=c}, de = {[house]=c}, recipes = { {prof, req, out, perInput, vendorRoute, v = {[h]=},
--   t = {[h]= "v"|"a"|"d"|"c"}, via = item the output is crafted into (t "c"), pattern} } }
function Exits.Decode(id)
  local U = ns.USES
  if not (U and type(U.items) == "table" and type(U.houses) == "table") then return nil end
  if cacheOf ~= U then cache, cacheOf = {}, U end
  local hit = cache[id]
  if hit ~= nil then return hit or nil end
  local s, out = U.items[id], false
  if type(s) == "string" then
    local p = Split(s, "|")
    local hs = U.houses
    out = { sell = tonumber(p[1]) or 0, keep = {}, de = {}, recipes = {} }
    local keep, de = Split(p[2] or "", ","), Split(p[3] or "", ",")
    for i, h in ipairs(hs) do out.keep[h], out.de[h] = tonumber(keep[i] or ""), tonumber(de[i] or "") end
    if p[4] and p[4] ~= "" then
      for _, rs in ipairs(Split(p[4], ";")) do
        local f = Split(rs, ",")
        local r = { prof = tonumber(f[1]), req = tonumber(f[2]) or 1, out = tonumber(f[3]),
          perInput = (tonumber(f[4]) or 1000) / 1000, vendorRoute = tonumber(f[5]), v = {}, t = {} }
        for i, h in ipairs(hs) do
          r.v[h] = tonumber(f[5 + 2 * i - 1] or "")
          local t = f[5 + 2 * i] or ""
          r.t[h] = t ~= "" and t:sub(1, 1) or nil
          r.via = r.via or tonumber(t:sub(2)) -- "c<item>": the output's own best exit is a craft into <item>
        end
        r.pattern = tonumber(f[6 + 2 * #hs] or "")
        r.spell = tonumber(f[7 + 2 * #hs] or "")
        if r.prof and r.out then out.recipes[#out.recipes + 1] = r end
      end
    end
  end
  cache[id] = out
  return out or nil
end

-- Impure: { [baseSkillLine] = rank + modifier } for the player's professions (GetProfessions: 7 slots on Forever,
-- Camelot Blizzard_ProfessionsFrame; GetProfessionInfo's 7th return is the skill line). Undocumented C APIs: pcall.
function Exits.Ranks()
  local out = {}
  if not (GetProfessions and GetProfessionInfo) then return out end
  local ok, a, b, c, d, e, f, g = pcall(GetProfessions)
  if not ok then return out end
  for _, idx in ipairs({ a or false, b or false, c or false, d or false, e or false, f or false, g or false }) do
    if type(idx) == "number" then
      local ok2, _, _, rank, _, _, _, line, mod = pcall(GetProfessionInfo, idx)
      if ok2 and type(rank) == "number" and type(line) == "number" and not (issecretvalue and (issecretvalue(rank) or issecretvalue(line))) then
        local m = (type(mod) == "number" and not (issecretvalue and issecretvalue(mod))) and mod or 0
        out[Exits.CHILD[line] or line] = rank + m
      end
    end
  end
  return out
end

-- Impure: does the player know this recipe? C_SpellBook.IsSpellKnown on the recipe spell, else the trade skill
-- recipe info's `learned` [TODO-INGAME: confirm either is true for learned tradeskill recipes on Forever].
function Exits.Known(spell)
  if type(spell) ~= "number" then return false end
  if C_SpellBook and C_SpellBook.IsSpellKnown then
    local ok, k = pcall(C_SpellBook.IsSpellKnown, spell)
    if ok and k == true then return true end
  end
  if C_TradeSkillUI and C_TradeSkillUI.GetRecipeInfo then
    local ok, info = pcall(C_TradeSkillUI.GetRecipeInfo, spell)
    if ok and type(info) == "table" and info.learned == true then return true end
  end
  return false
end

local function Name(id)
  local n = C_Item and C_Item.GetItemNameByID and C_Item.GetItemNameByID(id)
  if type(n) == "string" and n ~= "" then return n end
  if C_Item and C_Item.RequestLoadItemDataByID then pcall(C_Item.RequestLoadItemDataByID, id) end
  return format(L["item %d"], id)
end

local function Signed(c)
  local m = ns.Prices.Money(c < 0 and -c or c)
  return (c < 0 and "−" or "+") .. m
end

local function GainText(g, raw)
  local wins = g >= Exits.MIN_GAIN or (raw > 0 and g >= Exits.MIN_PCT * raw)
  return C(wins and GREEN or (g < 0 and RED or GREY), Signed(g))
end

-- Pure. opts = { house =, mode = "full"|"short", count = stack count or nil, ranks = Exits.Ranks() result,
-- known = function(recipeSpell) -> bool (Exits.Known), profName = function(skillLine) -> name }. A craft is doable when
-- its recipe is known, or it's a trainer recipe (no pattern) within your skill. Returns { {left, right}, ... } or nil.
function Exits.Lines(id, opts)
  local mode = opts.mode or "full"
  if mode == "off" then return nil end
  local d = Exits.Decode(id)
  if not d then return nil end
  local U, Money = ns.USES, ns.Prices.Money
  local h = opts.house
  local known = false
  for _, x in ipairs(U.houses) do if x == h then known = true end end
  if not known then h = U.houses[1] end
  local known = opts.known or function() return false end
  local ranks, profName = opts.ranks or {}, opts.profName or function(p) return U.profs and U.profs[p] or tostring(p) end
  local rows = {}

  -- Vendor, prominently: per unit, plus the stack.
  if d.sell > 0 then
    local txt = Money(d.sell) .. L["/u"]
    if opts.count and opts.count > 1 then txt = txt .. C(GREY, format(" · x%d ", opts.count)) .. Money(d.sell * opts.count) end
    rows[#rows + 1] = { C(YELLOW, L["Vendor"]), C(WHITE, txt) }
  else
    rows[#rows + 1] = { C(YELLOW, L["Vendor"]), C(GREY, L["can't be sold"]) }
  end

  local keep = d.keep[h]
  local raw = math.max(d.sell, keep or 0)
  local function Exit(r) -- "AH", "DE", "vendor" or "craft <item>"
    local t = r.t[h]
    if t == "c" and r.via then return L["craft"] .. " " .. Name(r.via) end
    return TAG[t] or "?"
  end
  -- Best use: the best exit you can take now (vendor, AH, disenchant, trainer crafts within your skill). A better
  -- craft behind a pattern or more skill is the grey "Upside" line: shown, never assumed.
  local best = { v = d.sell, text = L["vendor it"] }
  if keep and keep > best.v then best = { v = keep, text = format(L["AH here %s/u"], Money(keep)) } end
  local de = d.de[h]
  if de and de > best.v then best = { v = de, text = format(L["disenchant %s/u"], Money(de)) } end
  local up
  for _, r in ipairs(d.recipes) do
    local v = r.v[h]
    if v and v - raw >= math.min(Exits.MIN_GAIN, Exits.MIN_PCT * raw) then
      local txt = format("%s → %s → %s %s/u", profName(r.prof), Name(r.out), Exit(r), Signed(v - raw))
      local can = known(r.spell) or ((ranks[r.prof] or -1) >= r.req and not r.pattern)
      if can and v > best.v then
        best = { v = v, text = C(GREEN, txt) }
      elseif not can and (not up or v > up.v) then
        up = { v = v, text = txt .. (r.pattern and L[" (pattern)"] or format(L[" (needs %d)"], r.req)) }
      end
    end
  end
  rows[#rows + 1] = { C(YELLOW, L["Best use"]), best.text }
  if up and up.v > best.v then rows[#rows + 1] = { C(GREY, L["Upside"]), C(GREY, up.text) } end
  if mode ~= "full" then return rows end

  for _, r in ipairs(d.recipes) do
    local v = r.v[h]
    if v then
      local can = known(r.spell) or ((ranks[r.prof] or -1) >= r.req and not r.pattern)
      local left = format("   %s %d · %s%s", profName(r.prof), r.req, Name(r.out),
        r.pattern and C(GREY, L[" (pattern)"]) or "")
      local right = {}
      if r.vendorRoute then right[#right + 1] = L["vendor"] .. " " .. GainText(r.vendorRoute - raw, raw) end
      if r.t[h] and r.t[h] ~= "v" then right[#right + 1] = Exit(r) .. " " .. GainText(v - raw, raw) end
      rows[#rows + 1] = { can and left or C(GREY, left), concat(right, C(GREY, " · ")) }
    end
  end
  if de then rows[#rows + 1] = { "   " .. L["Disenchant"], GainText(de - raw, raw) } end
  return rows
end

function Exits.ProfName(line)
  if C_TradeSkillUI and C_TradeSkillUI.GetTradeSkillDisplayName then
    local ok, n = pcall(C_TradeSkillUI.GetTradeSkillDisplayName, line)
    if ok and type(n) == "string" and n ~= "" then return n end
  end
  local U = ns.USES
  return U and U.profs and U.profs[line] or tostring(line)
end
